export function createResilientFetch({
  fetch,
  sleep,
  random = Math.random,
  maxAttempts = 4,
  baseDelayMs = 200,
  maxDelayMs = 5000,
}) {
  const retryableStatuses = new Set([408, 429, 500, 502, 503, 504]);
  const retryableMethods = new Set(["GET", "HEAD", "OPTIONS", "PUT", "DELETE"]);

  function hasIdempotencyKey(headers) {
    if (headers == null) return false;

    if (typeof headers.get === "function") {
      return headers.get("Idempotency-Key") != null;
    }

    return Object.keys(headers).some(
      (name) => name.toLowerCase() === "idempotency-key"
    );
  }

  function backoffDelay(retryNumber) {
    return Math.floor(
      random() * Math.min(maxDelayMs, baseDelayMs * 2 ** (retryNumber - 1))
    );
  }

  return async function rfetch(url, options = {}) {
    const method = String(
      options.method === undefined ? "GET" : options.method
    ).toUpperCase();

    const canRetry =
      retryableMethods.has(method) ||
      ((method === "POST" || method === "PATCH") &&
        hasIdempotencyKey(options.headers));

    for (let attempt = 1; ; attempt += 1) {
      const signal = options.signal;
      if (signal && signal.aborted) {
        const error = new Error("The operation was aborted.");
        error.name = "AbortError";
        throw error;
      }

      let response;
      try {
        response = await fetch(url, options);
      } catch (error) {
        if (
          (error != null && error.name === "AbortError") ||
          !canRetry ||
          attempt >= maxAttempts
        ) {
          throw error;
        }

        const delayMs = backoffDelay(attempt);
        await sleep(delayMs, options.signal);
        continue;
      }

      if (
        response.ok === true ||
        !retryableStatuses.has(response.status) ||
        !canRetry ||
        attempt >= maxAttempts
      ) {
        return response;
      }

      const retryAfter = response.headers.get("Retry-After");
      let delayMs;

      if (
        typeof retryAfter === "string" &&
        retryAfter.length > 0 &&
        !/\D/.test(retryAfter)
      ) {
        delayMs = Number(retryAfter) * 1000;
        if (delayMs > maxDelayMs) {
          return response;
        }
      } else {
        delayMs = backoffDelay(attempt);
      }

      await sleep(delayMs, options.signal);
    }
  };
}
